import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { renderHook } from '@testing-library/react';
import { ActiveViewType } from '../enums';
import type { IDueActiveViewTabsService, TDueDashboardCountsResponse } from '../interfaces/services';

interface IQueryOptions {
    queryKey: readonly unknown[];
}

let mockActiveView: ActiveViewType = ActiveViewType.DUE_DILIGENCE;
let dashboardCounts: TDueDashboardCountsResponse | undefined;

const mockQueryStates: Record<string, unknown> = {
    filter: 'TODOS',
    liqFilter: 'TODOS',
    modelo: 'v2',
    loa: null,
    credor: null,
    broker: null,
    priority_level: null,
    responsavel_scope: null,
    investidor_scope: null,
    investidor: null,
    esfera: null,
    ente_devedor: null,
    estado_ente_devedor: null,
    coordenador: null,
    host: null,
    page: 1,
};

jest.mock('nuqs', () => ({
    parseAsInteger: { withDefault: () => ({}) },
    parseAsString: { withDefault: () => ({}) },
    useQueryStates: () => [mockQueryStates, jest.fn()],
}));

jest.mock('../hooks/use-due-diligence-active-view', () => ({
    useDueDiligenceActiveView: () => ({
        activeView: mockActiveView,
        setActiveView: jest.fn(),
        isTabDisabled: () => false,
    }),
}));

jest.mock('@tanstack/react-query', () => ({
    useQuery: (options: IQueryOptions) => {
        if (options.queryKey[1] === 'dashboard-counts') {
            return { data: dashboardCounts, isLoading: false };
        }
        if (options.queryKey[1] === 'liquidacao-counts') {
            return { data: undefined, isLoading: false };
        }
        return { data: [], isLoading: false };
    },
}));

jest.mock('@/store/userInfo', () => ({
    useUserInfoStore: (
        selector: (state: {
            data: { role: string; username: string; host: string };
        }) => unknown,
    ) => selector({ data: { role: 'JURIDICO_ANALISTA', username: 'analista', host: 'celer' } }),
}));

jest.mock('@/store/useBroker', () => ({
    useBrokerStore: (selector: (state: { isCoordenadorOrMaster: boolean }) => unknown) =>
        selector({ isCoordenadorOrMaster: false }),
}));

function buildDashboardCounts(concluida: number): TDueDashboardCountsResponse {
    return {
        todos: 40,
        revisao_valor_loa: 4,
        pre_due: 5,
        due_diligence: 6,
        revisao_due_diligence: 7,
        concluida,
        pendencias_impeditivas: 2,
        liquidacao_cessao_total: 0,
        arquivadas: 0,
    };
}

function buildService(): IDueActiveViewTabsService {
    return {
        get: jest.fn(async () => ({ count: 0, next: null, previous: null, results: [] })),
        getPendenciasAbertasSummary: jest.fn(async () => ({
            ativos_com_pendencia: 0,
            valor_liquido_total: 0,
        })),
        getPendenciasCount: jest.fn(async () => ({ total: 0 })),
        getRepactuacoesCount: jest.fn(async () => ({ total: 0 })),
        getDashboardCounts: jest.fn(async () => buildDashboardCounts(17)),
        getLiquidacaoCount: jest.fn(async () => ({
            todos: 0,
            aprovado_ressalva: 0,
            em_liquidacao: 0,
            em_cessao: 0,
        })),
    };
}

describe('useViewModelDiligenceFilter — fase CONCLUIDO', () => {
    beforeEach(() => {
        mockActiveView = ActiveViewType.DUE_DILIGENCE;
        dashboardCounts = buildDashboardCounts(17);
        mockQueryStates.filter = 'TODOS';
    });

    it('expõe Concluídos com a contagem concluida do dashboard', async () => {
        const { useViewModelDiligenceFilter } = await import(
            '../ViewModels/useViewModelDiligenceFilter'
        );
        const { result } = renderHook(() => useViewModelDiligenceFilter(buildService()));

        const concluidoOption = result.current.fieldHandlers.faseOptions.find(
            (option) => option.value === 'CONCLUIDO',
        );

        expect(concluidoOption).toEqual({
            value: 'CONCLUIDO',
            label: 'Concluídos (17)',
            count: 17,
        });
    });

    it('usa zero quando concluida não vem no dashboard', async () => {
        dashboardCounts = undefined;

        const { useViewModelDiligenceFilter } = await import(
            '../ViewModels/useViewModelDiligenceFilter'
        );
        const { result } = renderHook(() => useViewModelDiligenceFilter(buildService()));

        const concluidoOption = result.current.fieldHandlers.faseOptions.find(
            (option) => option.value === 'CONCLUIDO',
        );

        expect(concluidoOption?.count).toBe(0);
        expect(concluidoOption?.label).toBe('Concluídos (0)');
    });

    it('não inclui CONCLUIDO nas fases da vista de liquidação', async () => {
        mockActiveView = ActiveViewType.LIQUIDACAO;

        const { useViewModelDiligenceFilter } = await import(
            '../ViewModels/useViewModelDiligenceFilter'
        );
        const { result } = renderHook(() => useViewModelDiligenceFilter(buildService()));

        expect(
            result.current.fieldHandlers.faseOptions.some((option) => option.value === 'CONCLUIDO'),
        ).toBe(false);
    });
});

